# tools/buggy_build/ledger.py — writes docs/buggy/SPRITE_LEDGER.md + CREDITS.md from docs/buggy/frames.json.
#   python3 -I tools/buggy_build/ledger.py <repo-root>
import sys, os, json
ROOT = sys.argv[1]; D = os.path.join(ROOT, 'docs/buggy')
J = json.load(open(os.path.join(D, 'frames.json')))
ROWNAME = {1: 'idle (laugh) + small head + PORTRAIT', 2: 'walk', 3: 'cape-spread + white SILHOUETTE', 4: 'knife attacks (F3 = yellow throw streak)',
           5: 'arm-extended attack set (F2/F3 = hand already gone) + detached knife HAND', 6: 'SPLIT BODY', 7: 'orange CAPE shapes',
           8: 'kicks / acrobatic', 9: 'dive with knives', 10: 'low horizontal flight with knives', 11: 'horizontal flight with cape + airborne spread',
           12: 'SPINNING KNIFE BALL', 13: 'cannon-cart SILHOUETTE + cannon cart (side)', 14: 'cannon cart (front) + skull CANNONBALL + plain ball'}
L = ['# Buggy the Clown — Sprite Ledger', '',
     f"Source: `{J['source']}` (SHA-256 `{J['sha256']}`), GBA *One Piece* rip by Paddy. Cell {J['cell'][0]}x{J['cell'][1]}, feet origin {J['origin']}.",
     'Generated by `tools/buggy_build/extract.py` + `ledger.py`. Numbered contact sheet: `docs/buggy/contact_sheet.png`; mask check: `docs/buggy/masks_check.png`.', '',
     'Body/attack frames are stored **mirrored** (sheet faces left, engine stores right-facing and flips at runtime). Nearest-neighbour only, no resampling.',
     '**Derived copies** (never new art): masked rows 1-6 of every masked strip (part pixels cleared + joint disc L2P4 pasted on the stump), `fx_knife` (R4F3 streak pixels only), `part_legs` (L1P6 pasted over L3P1).', '',
     '## Real row counts (vs. the brief\'s read)', '', '| Row | Real frames | Brief said | Content |', '|---|---|---|---|']
BRIEF = {1: '4+head+portrait', 2: 4, 3: 2, 4: 4, 5: '4+hand', 6: 4, 7: 4, 8: 4, 9: 2, 10: 3, 11: 3, 12: 3, 13: '3-4', 14: 'cannon+ball+ball'}
for r in range(1, 15): L.append(f"| R{r} | {J['rowCounts'][r - 1]} | {BRIEF[r]} | {ROWNAME[r]} |")
L += [f"| L1-L10 (loose) | {sum(J['rowCounts'][14:24])} | many | loose body parts (see PARTS) |", '| last | 1 | sheep + credit | Going Merry figurehead + credit panel |', '',
      '## Frames → animations → trigger', '', '| # | Frame | Sheet rect (x0,y0,x1,y1) | Used by |', '|---|---|---|---|']
for k, (fid, f) in enumerate(J['frames'].items()):
    if fid.startswith('R'): L.append(f"| {k + 1} | {fid} | {tuple(f['rect'])} | {'; '.join(f['uses'])} |")
L += ['', 'Animation → move/state mapping lives in `buggyData.js` (normals/specials) and `buggyState.js` (states); every animation name above is the engine action or Buggy move key that plays it.', '',
      '## PARTS — every loose piece', '', '| # | Piece | Type | Rect | Slot / use |', '|---|---|---|---|---|']
for k, (fid, f) in enumerate(J['frames'].items()):
    if fid.startswith('L'): L.append(f"| {k + 1} | {fid} | {f['type']}{' — ' + f['note'] if f.get('note') else ''} | {tuple(f['rect'])} | {'; '.join(f['uses'])} |")
L += ['', '## Last row', '', f"| 104 | MERRY (x < 58) | Going Merry figurehead | {'; '.join(J['frames']['MERRY']['uses'])}. The art matches Zoro's emblem (same figurehead; this rip has a cleaner palette, {'' if J['merryIdentical'] else 'not pixel-identical'}) — per the brief the existing asset is reused, not duplicated. |",
      f"| — | credit panel {tuple(J['excluded']['credit_panel'])} | **excluded, credit** | \"Ripped by Paddy / No credit needed\" — see CREDITS.md. Never written to any output. |", '',
      f"Unused frames: {J['unused'] or 'none'} (the credit panel is the only exclusion).", '']
open(os.path.join(D, 'SPRITE_LEDGER.md'), 'w').write('\n'.join(L))
open(os.path.join(D, 'CREDITS.md'), 'w').write('\n'.join([
 '# Buggy the Clown — Credits', '',
 '* **Sprites:** Game Boy Advance *One Piece* (Buggy, enemy sheet), ripped by **Paddy** — the sheet reads "Ripped by Paddy / No credit needed". Credited anyway.',
 f"* The credit panel itself (sheet rect {tuple(J['excluded']['credit_panel'])}) is ledgered **excluded, credit** and is not used in the game.",
 '* **Going Merry emblem:** reuses `assets/zoro/merry.png` (Zoro build; same ripper).',
 '* **Sound:** all Buggy SFX are WebAudio synth placeholders generated in code (`buggySound.js`); no audio files.',
 '* *One Piece* © Eiichiro Oda / Shueisha / Toei Animation. Fan project.', '']))
print('ok', len(L))
